SELECT row_number() over () AS _uid_,* FROM (WITH center_point AS (     SELECT         poi_id,         name,         geom     FROM bj_life.service_poi     WHERE poi_id = 12345 ) SELECT     p.poi_id::integer AS objectid,     p.name,     c.service_class_name,     p.address,     ROUND(         ST_Distance(             p.geom,             center_point.geom         )::numeric,         1     ) AS distance_m,     p.geom FROM bj_life.service_poi p JOIN bj_life.service_category c   ON p.category_id = c.category_id CROSS JOIN center_point WHERE p.poi_id <> center_point.poi_id   AND ST_DWithin(         p.geom,         center_point.geom,         1000       )
) AS _subq_1_
